const results = await Promise.allSettled([
 tools.get_goal({}),
 tools.mcp__portal__portal_documentation({}),
 tools.mcp__portal__portal_screenshot({})
]);
for (let i=0;i<results.length;i++){const r=results[i];if(r.status==="fulfilled"){text({index:i,result:r.value});if(r.value?.content)for(const c of r.value.content)if(c.type==="image")image(c);}else text({index:i,error:String(r.reason)});}

